import fs from "node:fs";
import path from "node:path";
import { applyTemplateReplacements } from "../shared/templateReplacements.js";
import { sha256 } from "./bundled.js";
import { hasPlaceholder, matchesFingerprint, type FileFingerprint } from "./fingerprint.js";
import { assertSkillFilePath, assertSkillName, sameList } from "./names.js";

/** Shipped in the package's template directory, beside the skills it describes.
 *  Generated by scripts/generate-bundled-skill-history.mjs; not edited by hand. */
export const HISTORY_FILE = "bundled-skill-history.json";

const SCHEMA_VERSION = 1;
const SHA256_HEX = /^[0-9a-f]{64}$/;

/** One version of a skill that an earlier release shipped. */
export interface ShippedVersion {
  /** The first release tag that carried it. */
  since: string;
  files: Record<string, FileFingerprint>;
}

/**
 * What earlier releases shipped. A home that was installed before the sync kept a
 * receipt has no record of what was placed in it; this is how a skill in such a home
 * can still be shown to be an untouched shipped copy rather than the user's work.
 */
export interface ShippedHistory {
  /** Every skill name the package is known to have shipped. */
  names: ReadonlySet<string>;
  versions: Readonly<Record<string, readonly ShippedVersion[]>>;
}

/** No file is a package without history, not an error: nothing unrecorded is then
 *  recognised, which is the cautious reading. A file that is there but malformed is
 *  refused, like any other damage to the package. */
export function loadShippedHistory(templateDir: string): ShippedHistory {
  const file = path.join(templateDir, HISTORY_FILE);
  let text: string;
  try { text = fs.readFileSync(file, "utf8"); }
  catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return { names: new Set(), versions: {} };
    throw unusable(error);
  }
  try {
    return parseHistory(JSON.parse(text));
  } catch (error) {
    throw unusable(error);
  }
}

function unusable(error: unknown): Error {
  return new Error(`The package's ${HISTORY_FILE} cannot be used: ${error instanceof Error ? error.message : String(error)}`);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseHistory(parsed: unknown): ShippedHistory {
  if (!isRecord(parsed) || parsed.schemaVersion !== SCHEMA_VERSION) throw new Error(`it is not format ${SCHEMA_VERSION}`);
  if (!Array.isArray(parsed.names) || !isRecord(parsed.skills)) throw new Error('it needs "names" and "skills"');
  const versions = Object.fromEntries(Object.entries(parsed.skills).map(([name, list]) => {
    assertSkillName(name, "It");
    if (!Array.isArray(list)) throw new Error(`"${name}" is not a list of versions`);
    return [name, list.map((version) => parseVersion(name, version))];
  }));
  for (const name of parsed.names) assertSkillName(name, "It");
  return { names: new Set([...(parsed.names as string[]), ...Object.keys(versions)]), versions };
}

function parseVersion(name: string, version: unknown): ShippedVersion {
  if (!isRecord(version) || typeof version.since !== "string" || !isRecord(version.files)) {
    throw new Error(`a version of "${name}" needs "since" and "files"`);
  }
  const files = Object.fromEntries(Object.entries(version.files).map(([relative, fingerprint]) => {
    assertSkillFilePath(relative, "It");
    return [relative, parseFingerprint(`${name}/${relative}`, fingerprint)];
  }));
  if (!Object.hasOwn(files, "SKILL.md")) throw new Error(`a version of "${name}" has no SKILL.md`);
  return { since: version.since, files };
}

function parseFingerprint(label: string, fingerprint: unknown): FileFingerprint {
  if (!isRecord(fingerprint)) throw new Error(`${label} has no fingerprint`);
  if (typeof fingerprint.sha256 === "string" && SHA256_HEX.test(fingerprint.sha256)) return { sha256: fingerprint.sha256 };
  const { lines, masked, slots } = fingerprint;
  if (typeof lines !== "number" || !Number.isInteger(lines) || lines < 1 || typeof masked !== "string" || !SHA256_HEX.test(masked) || !isRecord(slots)) {
    throw new Error(`${label} has a fingerprint that is neither a hash nor a template`);
  }
  for (const [index, templateLine] of Object.entries(slots)) {
    if (!/^\d+$/.test(index) || Number(index) >= lines) throw new Error(`${label} has a placeholder line outside the file`);
    if (typeof templateLine !== "string" || templateLine.includes("\n") || !hasPlaceholder(templateLine)) {
      throw new Error(`${label} has a placeholder line that holds no placeholder`);
    }
  }
  return { lines, masked, slots: slots as Record<string, string> };
}

/**
 * If the directory is, file for file, one of these earlier shipped versions, return
 * the hashes of its files; otherwise null.
 *
 * `renderings` are the placeholder values the installer could have used. Every file
 * must match the same version under the same rendering: a mix of two releases, or of
 * two names, is not something any release installed.
 */
export function matchShippedVersion(
  directory: string,
  paths: readonly string[],
  versions: readonly ShippedVersion[],
  renderings: readonly Record<string, string>[],
): Record<string, string> | null {
  const sameFiles = versions.filter((version) => sameList(paths, Object.keys(version.files).sort()));
  if (sameFiles.length === 0) return null;
  const contents = paths.map((relative) => fs.readFileSync(path.join(directory, ...relative.split("/"))));
  const matched = sameFiles.some((version) => renderings.some((replacements) =>
    paths.every((relative, index) => matchesFingerprint(
      version.files[relative],
      contents[index],
      (templateLine) => applyTemplateReplacements(templateLine, replacements),
    ))));
  return matched ? Object.fromEntries(paths.map((relative, index) => [relative, sha256(contents[index])])) : null;
}
